---
name: pr-evidence
description: Upload verification screenshots to the Roam dev graph and get public image URLs plus a Markdown table for the PR body. Use after a verification run produced PNGs and before create-pr writes the Evidence section.
---

# PR evidence upload

Uploads PNGs through `roamAlphaAPI.file.upload` in an authenticated Roam Playwright slot, files them under a page in the slot's graph (`discourse-dev-graph`), and emits a Markdown table that create-pr pastes into the Evidence section.

## When to use

- After verification (Roam `load-extension` run, Obsidian CDP run, manual captures) left PNGs on disk.
- Before create-pr builds the body. Roam PRs: reuse the verification's slot once that run has closed. Obsidian PRs: omit `--slot`.

## Command

Run from the worktree root, using the worktree's own `tsx` so the relative PNG paths and the repo's Playwright resolve:

```sh
./apps/roam/node_modules/.bin/tsx ~/.claude/skills/pr-evidence/upload.ts \
  [--slot N] [--branch <b>] [--label "<YYYY-MM-DD · shortsha · harness>"] [--harness <name>] \
  [--out table.md] [--settle-ms 5000] \
  shot1.png="Empty state" shot2.png="After import" ...
```

- `pnpm --filter roam exec tsx ...` also works, but it changes cwd to `apps/roam`, so pass absolute PNG paths.
- `--branch` defaults to the current git branch. `--label` defaults to `<today> · <short sha> · <--harness or "manual">`.
- Caption defaults to the file name without extension.
- No `--slot`: tries each configured slot (1, 2, 3) and moves on only on a profile-lock error.
- Headless by default (`HEADLESS=false` to watch).

## Output contract

- stdout: JSON `{page, pageUid, branchBlockUid, runBlockUid, items: [{caption, url, blockUid}]}`.
- stderr: `Markdown table: <path>`. The file defaults to `pr-evidence-<runBlockUid>.md` next to the first PNG and contains `| Scenario | Screenshot |` rows with `![caption](url)`. create-pr pastes it as-is.
- URLs are public Firebase storage links (`200 image/png` without cookies, verified 2026-09-23).

## Roam structure

```
Trang test/                       (page, found or created)
  <branch>                        (top-level block, reused on every run)
    <date · sha · harness>        (new run block per invocation, appended last)
      <caption> ![](<url>)        (one per PNG)
```

## Gotchas

- Imports `apps/roam/scripts/playwright/roamSession.ts` from the current worktree (`git rev-parse --show-toplevel`), so profiles live in that worktree's `local/roam-playwright/profiles/` unless `DG_ROAM_PLAYWRIGHT_PROFILE_DIR_<n>` is set.
- A slot's profile can only be open once. Close the verification session first, never delete lock files.
- Login errors (expired session, 2FA) come from `openRoamSession`; recover with `pnpm --filter roam playwright:open -- --slot N --headed --allow-login`, then rerun.
- Never print values from `apps/roam/.env`.
- Uploads cannot be rolled back and Roam cannot list graph files, so don't loop retries on a failing run.
- tsx injects `__name()` into functions passed to `page.evaluate`; the script shims it in the page first. Keep that shim if you edit the in-page code.
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

const PAGE_TITLE = "Trang test/";
const SLOTS = ["1", "2", "3"] as const;

type Item = { caption: string; url: string; blockUid: string };
type Upload = { name: string; caption: string; base64: string };
type Result = {
  page: string;
  pageUid: string;
  branchBlockUid: string;
  runBlockUid: string;
  items: Item[];
};
// Minimal shapes of the worktree's roamSession exports; typed imports can't use a runtime path.
type Session = { page: PlaywrightPage; close: () => Promise<void> };
type PlaywrightPage = {
  waitForFunction: (fn: string, arg?: unknown, opts?: { timeout: number }) => Promise<unknown>;
  evaluate: <R, A>(fn: (arg: A) => R | Promise<R>, arg: A) => Promise<R>;
  waitForTimeout: (ms: number) => Promise<void>;
};
type RoamSessionModule = {
  openRoamSession: (opts: { slot: string; timeout?: number }) => Promise<Session>;
  resolveSlotConfig: (opts: { slot: string }) => unknown;
};

const git = (args: string[]): string =>
  execFileSync("git", args, { encoding: "utf8" }).trim();

const parseCli = (
  argv: string[],
): { flags: Record<string, string>; files: string[] } => {
  const flags: Record<string, string> = {};
  const files: string[] = [];
  for (let i = 0; i < argv.length; i += 1) {
    if (argv[i].startsWith("--")) flags[argv[i].slice(2)] = argv[++i] ?? "";
    else files.push(argv[i]);
  }
  return { flags, files };
};

const toUpload = (spec: string): Upload & { file: string } => {
  const eq = spec.indexOf("=");
  const file = path.resolve(eq === -1 ? spec : spec.slice(0, eq));
  if (!fs.existsSync(file)) throw new Error(`No such file: ${file}`);
  const name = path.basename(file);
  const caption =
    eq === -1 ? name.replace(/\.[^.]+$/, "") : spec.slice(eq + 1).trim();
  return { file, name, caption, base64: fs.readFileSync(file).toString("base64") };
};

const loadRoamSession = async (root: string): Promise<RoamSessionModule> => {
  const mod = await import(path.join(root, "apps/roam/scripts/playwright/roamSession.ts"));
  return (mod.openRoamSession ? mod : mod.default) as RoamSessionModule;
};

const isProfileLock = (error: unknown): boolean =>
  error instanceof Error && /profile is already in use/i.test(error.message);

const configuredSlots = (roam: RoamSessionModule): string[] =>
  SLOTS.filter((slot) => {
    try {
      roam.resolveSlotConfig({ slot });
      return true;
    } catch {
      return false;
    }
  });

const openSession = async ({
  roam,
  slot,
}: {
  roam: RoamSessionModule;
  slot?: string;
}): Promise<Session> => {
  if (slot) return roam.openRoamSession({ slot, timeout: 60_000 });
  const candidates = configuredSlots(roam);
  if (candidates.length === 0) throw new Error("No Roam Playwright slot is configured in apps/roam/.env.");
  for (const candidate of candidates) {
    try {
      return await roam.openRoamSession({ slot: candidate, timeout: 60_000 });
    } catch (error) {
      if (!isProfileLock(error) || candidate === candidates.at(-1)) throw error;
      console.error(`Slot ${candidate} is locked; trying the next slot.`);
    }
  }
  throw new Error("unreachable");
};

// Runs in the browser; everything it uses must be defined inside it.
const writeEvidence = async ({
  title,
  branch,
  label,
  uploads,
}: {
  title: string;
  branch: string;
  label: string;
  uploads: Upload[];
}): Promise<Omit<Result, "page">> => {
  const api = (window as any).roamAlphaAPI;
  const uid = (): string => api.util.generateUID();
  const createBlock = async (parentUid: string, text: string): Promise<string> => {
    const blockUid = uid();
    await api.data.block.create({
      location: { "parent-uid": parentUid, order: "last" },
      block: { string: text, uid: blockUid },
    });
    return blockUid;
  };
  const extractUrl = (ret: string): string | undefined => {
    const u = String.raw`(https?://\S+?)`;
    const patterns = [
      new RegExp(String.raw`^!\[[^\]]*\]\(${u}\)$`),
      new RegExp(String.raw`^\{\{\[\[(?:pdf|audio|video)\]\]:\s*${u}\s*\}\}$`),
      new RegExp(String.raw`^\{\{(?:pdf|audio|video):\s*${u}\s*\}\}$`),
      new RegExp(String.raw`^\[[^\]]*\]\(${u}\)$`),
      new RegExp(String.raw`^${u}$`),
    ];
    for (const p of patterns) {
      const m = ret.trim().match(p)?.[1];
      if (m) return m;
    }
    return undefined;
  };

  let pageUid: string | null = api.q(
    "[:find ?u . :in $ ?t :where [?p :node/title ?t] [?p :block/uid ?u]]",
    title,
  );
  if (!pageUid) {
    pageUid = uid();
    await api.data.page.create({ page: { title, uid: pageUid } });
  }
  let branchBlockUid: string | null = api.q(
    "[:find ?u . :in $ ?pu ?s :where [?p :block/uid ?pu] [?p :block/children ?c] [?c :block/string ?s] [?c :block/uid ?u]]",
    pageUid,
    branch,
  );
  if (!branchBlockUid) branchBlockUid = await createBlock(pageUid, branch);
  const runBlockUid = await createBlock(branchBlockUid, label);

  const items: Item[] = [];
  for (const upload of uploads) {
    const bytes = Uint8Array.from(atob(upload.base64), (c) => c.charCodeAt(0));
    const file = new File([bytes], upload.name, { type: "image/png" });
    const ret: string = await api.file.upload({ file, toast: { hide: true } });
    const url = extractUrl(ret);
    if (!url) throw new Error(`Unreadable file.upload result for ${upload.name}: ${ret}`);
    const blockUid = await createBlock(runBlockUid, `${upload.caption} ![](${url})`);
    items.push({ caption: upload.caption, url, blockUid });
  }
  return { pageUid, branchBlockUid, runBlockUid, items };
};

const markdownTable = (items: Item[]): string =>
  [
    "| Scenario | Screenshot |",
    "| --- | --- |",
    ...items.map((i) => `| ${i.caption.replace(/\|/g, "\\|")} | ![${i.caption.replace(/[\[\]|]/g, "")}](${i.url}) |`),
  ].join("\n") + "\n";

const main = async (): Promise<void> => {
  const { flags, files } = parseCli(process.argv.slice(2));
  if (files.length === 0) throw new Error("Pass at least one PNG: upload.ts [--slot N] [--branch b] [--label l] a.png[=caption]...");
  const specs = files.map(toUpload);
  const root = git(["rev-parse", "--show-toplevel"]);
  const branch = flags.branch || git(["rev-parse", "--abbrev-ref", "HEAD"]);
  const label =
    flags.label ||
    `${new Date().toISOString().slice(0, 10)} · ${git(["rev-parse", "--short", "HEAD"])} · ${flags.harness || "manual"}`;

  const roam = await loadRoamSession(root);
  const session = await openSession({ roam, slot: flags.slot });
  try {
    const { page } = session;
    await page.waitForFunction("!!window.roamAlphaAPI?.file?.upload && !!window.roamAlphaAPI?.data?.block", undefined, { timeout: 60_000 });
    // tsx (esbuild keepNames) wraps inner functions in __name(), which the page lacks.
    await page.evaluate(() => { (globalThis as any).__name ??= (f: unknown) => f; }, undefined);
    const written = await page.evaluate(writeEvidence, {
      title: PAGE_TITLE,
      branch,
      label,
      uploads: specs.map(({ name, caption, base64 }) => ({ name, caption, base64 })),
    });
    // Block writes sync to Roam's backend asynchronously; give them time before closing.
    await page.waitForTimeout(Number(flags["settle-ms"] || 5000));
    const result: Result = { page: PAGE_TITLE, ...written };
    const outPath = path.resolve(
      flags.out || path.join(path.dirname(specs[0].file), `pr-evidence-${result.runBlockUid}.md`),
    );
    fs.writeFileSync(outPath, markdownTable(result.items));
    process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
    console.error(`Markdown table: ${outPath}`);
  } finally {
    await session.close();
  }
};

main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : error);
  process.exit(1);
});
