name: obsidian-vault
description: Lease an Obsidian test vault to the current worktree so its dev watcher and CDP runs never collide with another branch's. Use whenever starting the apps/obsidian dev watcher, building the plugin into a vault, choosing or switching which vault a branch uses, asking "which vault is free?", or when a build seems to have been overwritten by another worktree.
---

# Obsidian vault leases

One script, `~/.claude/skills/obsidian-vault/scripts/vault.mjs`, owns which worktree builds into which vault. Pass `--worktree <abs path>` on every call: the Bash cwd resets to the main repo between calls.

```sh
V=~/.claude/skills/obsidian-vault/scripts/vault.mjs
node $V status                          # every vault: free | idle | live, holder, watcher, CDP run
node $V dev --worktree <wt>             # claim + start the watcher (run_in_background)
node $V claim --worktree <wt>           # claim without starting anything
node $V claim --worktree <wt> --take <vault>   # only after the user approved it
node $V release --worktree <wt>         # stop this worktree's watcher, free its vault
node $V path --worktree <wt>            # print the leased plugin dir
```

## Pools

The registry at `~/.claude/state/obsidian-vaults.json` holds the pool and the leases. Edit its `vaults` array to add or remove vaults.

- `--db local` (default): dgDevVault, testVault, testVault2, Obsidian Vault. Normal dev work.
- `--db production`: testVault123. Use only when Trang asks to test against the prod database.

## The worktree's `.env` follows the lease

The lease is the source of truth, and `<worktree>/apps/obsidian/.env` mirrors it. Every claim writes `OBSIDIAN_PLUGIN_PATH` and `SUPABASE_USE_DB` there and keeps the other lines. A plain `pnpm dev`, `vault.mjs dev` and `dg-obsidian-cdp-verify` therefore all build into the same vault.

- A takeover clears the losing worktree's two keys, but only if they still point at that vault, so its next `pnpm dev` doesn't mirror anywhere.
- `release` clears them the same way.
- Don't hand-edit these keys. Claim or `--take` instead, or the `.env` and the registry disagree.
- A running watcher read `.env` at startup. If `claim` prints `restartWatcher`, restart `pnpm dev`.

## States

- **free**: no lease, nothing running. `claim` takes it silently.
- **idle**: leased to a worktree, but no watcher or CDP run. The session may still be alive and planning.
- **live**: an apps/obsidian `dev.ts` watcher mirrors into it (leased or not, found via `ps` + `lsof` cwd), or a `dg-obsidian-cdp-verify` run holds its lock.

A worktree re-claiming gets its own vault back. A lease frees itself only when its worktree directory is gone, or on `release`.

## When `claim` or `dev` exits 2

No free vault is left in that pool. **Never pick one yourself.**

1. Read the printed `candidates` (vault, state, holder branch, since, cdpRun).
2. Call `mcp__ccd_session_mgmt__list_sessions` (load it with ToolSearch) and note whether a session is active on each holder branch.
3. Ask Trang with AskUserQuestion: one option per vault, labelled with its state, its holder and whether that holder's session is active.
4. Only on a yes, rerun with `--take <vault>`. On a live vault, this SIGTERMs the holder's watcher. A vault with a running CDP run can't be taken; wait for it.

## After claiming

- Open the vault in Obsidian with the printed `obsidian://open?path=` URL, and reload the plugin.
- `dg-obsidian-cdp-verify` uses the lease automatically when no `--slot` is given.
#!/usr/bin/env node
// Leases Obsidian test vaults to worktrees so dev watchers and CDP runs never share a plugin dir.
//   node vault.mjs status [--json]
//   node vault.mjs claim   [--worktree <path>] [--db local|production] [--take <vault>]
//   node vault.mjs dev     [--worktree <path>] [--db local|production] [--take <vault>]
//   node vault.mjs release [--worktree <path>] [--db local|production]
//   node vault.mjs path    [--worktree <path>] [--db local|production]
import { execFileSync, spawn, spawnSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { pathToFileURL } from "node:url";

const STATE_DIR = path.join(os.homedir(), ".claude", "state");
export const REGISTRY = path.join(STATE_DIR, "obsidian-vaults.json");
const MUTEX = `${REGISTRY}.lock`;
const DOCS = path.join(os.homedir(), "Documents");

// Seed only; edit the registry file to change the pool.
const DEFAULT_POOL = [
  { name: "dgDevVault", db: "local" },
  { name: "testVault", db: "local" },
  { name: "testVault2", db: "local" },
  { name: "Obsidian Vault", db: "local" },
  { name: "testVault123", db: "production" },
].map((v) => ({
  ...v,
  root: path.join(DOCS, v.name),
  pluginDir: path.join(DOCS, v.name, ".obsidian", "plugins", "discourse-graphs"),
}));

const exitError = (message, exitCode, extra = {}) =>
  Object.assign(new Error(message), { exitCode, ...extra });

const sh = (cmd, args) => spawnSync(cmd, args, { encoding: "utf8" }).stdout ?? "";

export const resolveWorktree = (from = process.cwd()) =>
  execFileSync("git", ["-C", from, "rev-parse", "--show-toplevel"], { encoding: "utf8" }).trim();

const currentBranch = (worktree) => {
  try {
    return execFileSync("git", ["-C", worktree, "branch", "--show-current"], { encoding: "utf8" }).trim() || "(detached)";
  } catch {
    return "(gone)";
  }
};

export const isPidAlive = (pid) => {
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    return error.code === "EPERM";
  }
};

const loadRegistry = () =>
  existsSync(REGISTRY) ? JSON.parse(readFileSync(REGISTRY, "utf8")) : { vaults: DEFAULT_POOL, leases: {} };

const saveRegistry = (reg) => {
  mkdirSync(STATE_DIR, { recursive: true });
  writeFileSync(REGISTRY, `${JSON.stringify(reg, null, 2)}\n`);
};

// mkdir is atomic, so two agents claiming at once can't both see the same vault free.
const withRegistry = async (fn) => {
  mkdirSync(STATE_DIR, { recursive: true });
  const deadline = Date.now() + 10000;
  for (;;) {
    try {
      mkdirSync(MUTEX);
      break;
    } catch {
      if (Date.now() - statSync(MUTEX, { throwIfNoEntry: false })?.mtimeMs > 30000) rmSync(MUTEX, { recursive: true, force: true });
      else if (Date.now() > deadline) throw exitError(`registry busy: ${MUTEX}`, 1);
      await new Promise((r) => setTimeout(r, 100));
    }
  }
  try {
    const reg = loadRegistry();
    const result = await fn(reg);
    saveRegistry(reg);
    return result;
  } finally {
    rmSync(MUTEX, { recursive: true, force: true });
  }
};

const readEnvValue = (file, key) => {
  if (!existsSync(file)) return undefined;
  const line = readFileSync(file, "utf8").split("\n").find((l) => l.trim().startsWith(`${key}=`));
  return line?.slice(line.indexOf("=") + 1);
};

// The worktree's .env mirrors its lease so plain `pnpm dev`, vault.mjs dev and CDP runs all target one vault.
const ENV_KEYS = ["OBSIDIAN_PLUGIN_PATH", "SUPABASE_USE_DB"];
const syncEnv = (worktree, vault) => {
  const file = path.join(worktree, "apps", "obsidian", ".env");
  if (!vault && !existsSync(file)) return;
  const kept = (existsSync(file) ? readFileSync(file, "utf8") : "")
    .split("\n")
    .filter((l) => l && !ENV_KEYS.some((k) => l.trim().startsWith(`${k}=`)));
  const added = vault ? [`OBSIDIAN_PLUGIN_PATH='${JSON.stringify([vault.pluginDir])}'`, `SUPABASE_USE_DB=${vault.db}`] : [];
  writeFileSync(file, `${[...kept, ...added].join("\n")}\n`);
};

// Only clears a worktree's .env if it still points at this vault, so a newer lease isn't wiped.
const clearEnvIfPointsAt = (worktree, vault) => {
  if (existsSync(worktree) && readEnvValue(path.join(worktree, "apps", "obsidian", ".env"), "OBSIDIAN_PLUGIN_PATH")?.includes(vault.pluginDir))
    syncEnv(worktree, null);
};

// Every running apps/obsidian dev.ts, wherever it came from, mapped to the vault plugin dirs it mirrors into.
// Paths can contain spaces, so the mirror is matched by substring, not by tokenizing `ps eww`.
export const scanWatchers = (vaults) => {
  const byWorktree = new Map();
  for (const line of sh("ps", ["-axo", "pid=,command="]).split("\n")) {
    if (!/scripts\/dev\.ts/.test(line)) continue;
    const pid = Number(line.trim().split(/\s+/)[0]);
    const cwd = sh("lsof", ["-a", "-p", String(pid), "-d", "cwd", "-Fn"]).split("\n").find((l) => l.startsWith("n"))?.slice(1);
    if (!cwd?.endsWith(`${path.sep}apps${path.sep}obsidian`)) continue;
    const worktree = path.dirname(path.dirname(cwd));
    const envLine = sh("ps", ["eww", "-o", "command=", "-p", String(pid)]);
    const envIdx = envLine.indexOf("OBSIDIAN_PLUGIN_PATH=");
    const mirror = envIdx !== -1 ? envLine.slice(envIdx) : readEnvValue(path.join(cwd, ".env"), "OBSIDIAN_PLUGIN_PATH") ?? "";
    const entry = byWorktree.get(worktree) ?? { worktree, pids: [], vaults: new Set() };
    entry.pids.push(pid);
    for (const v of vaults) if (mirror.includes(v.pluginDir)) entry.vaults.add(v.name);
    byWorktree.set(worktree, entry);
  }
  return [...byWorktree.values()].map((w) => ({ ...w, vaults: [...w.vaults] }));
};

const readCdpLock = (root) => {
  const file = path.join(root, ".obsidian", "dg-verify.lock");
  if (!existsSync(file)) return null;
  try {
    const lock = JSON.parse(readFileSync(file, "utf8"));
    return isPidAlive(lock.pid) ? lock : null;
  } catch {
    return null;
  }
};

// Leases whose worktree was deleted free themselves; nothing else expires.
const pruneLeases = (reg) => {
  for (const [name, lease] of Object.entries(reg.leases))
    if (!existsSync(lease.worktree) || !reg.vaults.some((v) => v.name === name)) delete reg.leases[name];
};

export const describe = (reg) => {
  pruneLeases(reg);
  const watchers = scanWatchers(reg.vaults);
  return reg.vaults.map((v) => {
    const lease = reg.leases[v.name] ?? null;
    const vWatchers = watchers.filter((w) => w.vaults.includes(v.name));
    const cdp = readCdpLock(v.root);
    const state = vWatchers.length || cdp ? "live" : lease ? "idle" : "free";
    return { ...v, state, lease: lease && { ...lease, currentBranch: currentBranch(lease.worktree) }, watchers: vWatchers, cdp };
  });
};

const stopWatchers = (watchers) => {
  for (const w of watchers)
    for (const pid of w.pids) {
      try {
        process.kill(pid, "SIGTERM");
      } catch {}
    }
};

const leaseFor = (states, worktree, db) => states.find((s) => s.lease?.worktree === worktree && s.db === db);

export const claim = async ({ worktree, db = "local", take }) =>
  withRegistry((reg) => {
    const states = describe(reg);
    const branch = currentBranch(worktree);
    const others = (s) => s.watchers.filter((w) => w.worktree !== worktree);
    const grant = (s) => {
      const prev = leaseFor(states, worktree, db);
      if (prev && prev.name !== s.name) delete reg.leases[prev.name];
      if (s.lease && s.lease.worktree !== worktree) clearEnvIfPointsAt(s.lease.worktree, s);
      reg.leases[s.name] = { worktree, branch, claimedAt: new Date().toISOString() };
      syncEnv(worktree, s);
      return { ...s, lease: reg.leases[s.name] };
    };
    // A watcher reads .env once at startup, so one aimed elsewhere keeps building there until restarted.
    const staleWatchers = (s) => scanWatchers(reg.vaults).filter((w) => w.worktree === worktree && !w.vaults.includes(s.name));
    const result = (r) => {
      const stale = staleWatchers(r.vault);
      return stale.length ? { ...r, restartWatcher: `pids ${stale.flatMap((w) => w.pids).join(",")} still build elsewhere; restart pnpm dev` } : r;
    };

    if (take) {
      const target = states.find((s) => s.name === take);
      if (!target) throw exitError(`unknown vault ${take}; pool: ${states.map((s) => s.name).join(", ")}`, 1);
      if (target.db !== db) throw exitError(`${take} is a ${target.db}-db vault; pass --db ${target.db}`, 1);
      if (target.cdp && target.cdp.branch !== branch)
        throw exitError(`${take} has a CDP run in progress (pid ${target.cdp.pid}, ${target.cdp.branch}); wait for it`, 1);
      stopWatchers(others(target));
      return result({ action: "took-over", from: target.lease?.branch ?? null, stopped: others(target).flatMap((w) => w.pids), vault: grant(target) });
    }

    const mine = leaseFor(states, worktree, db);
    if (mine) {
      syncEnv(worktree, mine);
      return result({ action: "reused", vault: mine, conflicts: others(mine) });
    }

    const free = states.find((s) => s.db === db && !s.lease && !s.cdp && !others(s).length);
    if (free) return result({ action: "claimed", vault: grant(free) });

    const candidates = states
      .filter((s) => s.db === db)
      .map((s) => ({
        vault: s.name,
        state: s.state,
        holder: s.lease?.currentBranch ?? s.watchers[0]?.worktree ?? null,
        worktree: s.lease?.worktree ?? s.watchers[0]?.worktree ?? null,
        since: s.lease?.claimedAt ?? null,
        cdpRun: Boolean(s.cdp),
      }));
    throw exitError(
      `No free ${db}-db vault. Ask the user which one ${branch} may take over (idle = leased, nothing running; ` +
        `live = a watcher or CDP run is using it and will be stopped), then rerun with --take <vault>.`,
      2,
      { candidates },
    );
  });

export const release = async ({ worktree, db }) =>
  withRegistry((reg) => {
    const states = describe(reg);
    const released = [];
    for (const s of states) {
      if (s.lease?.worktree !== worktree || (db && s.db !== db)) continue;
      stopWatchers(s.watchers.filter((w) => w.worktree === worktree));
      clearEnvIfPointsAt(worktree, s);
      delete reg.leases[s.name];
      released.push(s.name);
    }
    return { released };
  });

// Read-only lookup used by dg-obsidian-cdp-verify.
export const leasedVault = ({ worktree, db = "local" }) => {
  const reg = loadRegistry();
  pruneLeases(reg);
  const name = Object.entries(reg.leases).find(([n, l]) => l.worktree === worktree && reg.vaults.find((v) => v.name === n)?.db === db)?.[0];
  return name ? reg.vaults.find((v) => v.name === name) : null;
};

const dev = async ({ worktree, db, take }) => {
  const result = await claim({ worktree, db, take });
  const { vault } = result;
  const own = vault.watchers?.find((w) => w.worktree === worktree);
  console.log(JSON.stringify({ action: result.action, vault: vault.name, pluginDir: vault.pluginDir, db: vault.db, ...(result.stopped && { stopped: result.stopped }) }));
  if (own) {
    console.log(`watcher already running for this worktree (pids ${own.pids.join(", ")}); not starting another`);
    return;
  }
  const appDir = path.join(worktree, "apps", "obsidian");
  const tsx = path.join(appDir, "node_modules", ".bin", "tsx");
  if (!existsSync(tsx)) throw exitError(`no tsx at ${tsx}; run pnpm install in ${worktree}`, 1);
  // Explicit env beats dotenv, so the worktree's .env can't redirect the mirror.
  const child = spawn(tsx, ["scripts/dev.ts"], {
    cwd: appDir,
    stdio: "inherit",
    env: { ...process.env, OBSIDIAN_PLUGIN_PATH: JSON.stringify([vault.pluginDir]), SUPABASE_USE_DB: vault.db },
  });
  console.log(`watcher pid ${child.pid} -> ${vault.pluginDir} (SUPABASE_USE_DB=${vault.db})`);
  console.log(`open in Obsidian: obsidian://open?path=${encodeURIComponent(vault.root)}`);
  for (const sig of ["SIGINT", "SIGTERM", "SIGHUP"]) process.on(sig, () => child.kill(sig));
  await new Promise((resolve) => child.on("exit", (code) => resolve((process.exitCode = code ?? 0))));
};

const printStatus = (states) => {
  const rows = states.map((s) => [
    s.name,
    s.db,
    s.state,
    s.lease ? s.lease.currentBranch : "-",
    s.watchers.map((w) => (s.lease?.worktree === w.worktree ? `pid ${w.pids[0]}` : `pid ${w.pids[0]} (${path.basename(w.worktree)}, unleased)`)).join("; ") || "-",
    s.cdp ? `cdp pid ${s.cdp.pid}` : "-",
  ]);
  const head = ["vault", "db", "state", "lease", "watcher", "cdp"];
  const widths = head.map((h, i) => Math.max(h.length, ...rows.map((r) => r[i].length)));
  for (const r of [head, ...rows]) console.log(r.map((c, i) => c.padEnd(widths[i])).join("  "));
};

const parseArgs = (argv) => {
  const out = { _: [] };
  for (let i = 0; i < argv.length; i++) {
    if (!argv[i].startsWith("--")) out._.push(argv[i]);
    else out[argv[i].slice(2)] = argv[i + 1] && !argv[i + 1].startsWith("--") ? argv[++i] : true;
  }
  return out;
};

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const args = parseArgs(process.argv.slice(2));
  const [cmd = "status"] = args._;
  const worktree = args.worktree ? path.resolve(args.worktree) : cmd === "status" ? null : resolveWorktree();
  const db = args.db ?? "local";
  try {
    if (cmd === "status") {
      const states = await withRegistry(describe);
      args.json ? console.log(JSON.stringify(states, null, 2)) : printStatus(states);
    } else if (cmd === "claim") console.log(JSON.stringify(await claim({ worktree, db, take: args.take }), null, 2));
    else if (cmd === "release") console.log(JSON.stringify(await release({ worktree, db: args.db })));
    else if (cmd === "path") {
      const v = leasedVault({ worktree, db });
      if (!v) throw exitError(`no ${db}-db lease for ${worktree}; run claim`, 1);
      console.log(v.pluginDir);
    } else if (cmd === "dev") await dev({ worktree, db, take: args.take });
    else throw exitError(`unknown command ${cmd}`, 1);
  } catch (error) {
    console.error(error.message);
    if (error.candidates) console.log(JSON.stringify({ candidates: error.candidates }, null, 2));
    process.exitCode = error.exitCode ?? 1;
  }
}
